import java.util.Scanner;

public class Main {
    static long P, K;
    static boolean[] visited = new boolean[1000000];
    static final long MOD = 1000000007;

    static void explore(long current) {
        if (visited[(int) current]) return;
        visited[(int) current] = true;
        explore((current * K) % P);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        P = sc.nextLong();
        K = sc.nextLong();
        long result = 1;
        if (K == 1) {
            result = (result * P) % MOD;
        }
        for (long i = 1; i < P; i++) {
            if (!visited[(int) i]) {
                explore(i);
                result = (result * P) % MOD;
            }
        }
        System.out.println(result);
        sc.close();
    }
}
